//! #823/#824/#826/#828 p2 lowering-valve MCP handlers (buffs, upgrades, destructible/doodad
//! types, Game Interface), generated by a shared handler macro over the #829 valve. Split out of
//! `mcp_object_tools_lowering` to hold the <500-line ratchet.

use litd_engine::EngineError;
use serde_json::{Value, json};

use super::super::{
    LOWER_BUFF_TOOL, LOWER_DESTRUCTIBLE_DOODAD_TOOL, LOWER_GAME_INTERFACE_TOOL, LOWER_UPGRADE_TOOL,
    LowerUnitArgs, McpDomainTool, McpObjectToolCallOutput, READ_LOWERED_BUFF_TOOL,
    READ_LOWERED_DESTRUCTIBLE_DOODAD_TOOL, READ_LOWERED_GAME_INTERFACE_TOOL,
    READ_LOWERED_UPGRADE_TOOL, ReadLoweredUnitArgs, output, parse_args, validate_path,
    validate_single_line,
};

/// Serialize a lowered p2 readback into the shared `lowered_artifact` result envelope.
fn p2_artifact<T: serde::Serialize>(
    readback: &crate::object_editor::lower::LoweredTomlReadback<T>,
) -> Result<Value, EngineError> {
    let record = serde_json::to_value(&readback.document).map_err(|error| {
        EngineError::SerializationFailed {
            format: "json",
            reason: format!("encode lowered p2 record failed: {error}"),
        }
    })?;
    Ok(json!({
        "lowered_artifact": {
            "artifact_path": readback.path,
            "fingerprint": readback.fingerprint,
            "sha256": readback.sha256,
            "bytes": readback.bytes,
            "record": record,
        }
    }))
}

/// Generate a `lower_*` + `read_lowered_*` MCP handler pair for a p2 object-data editor. Each
/// lowers straight from the persisted (Aster) document -- never caller memory -- through the
/// #829 valve to a fingerprinted, project-confined litd/data TOML re-read from disk.
macro_rules! p2_lowering_handlers {
    (
        $lower_handler:ident, $read_handler:ident,
        $lower_tool:ident, $read_tool:ident,
        $lower_fn:path, $write_fn:path, $read_fn:path,
        $source:literal
    ) => {
        pub(crate) fn $lower_handler(
            route: McpDomainTool,
            arguments: Value,
        ) -> Result<McpObjectToolCallOutput, EngineError> {
            let args: LowerUnitArgs = parse_args($lower_tool, arguments)?;
            validate_path("document_path", &args.document_path)?;
            validate_path("artifact_path", &args.artifact_path)?;
            validate_single_line("object_id", &args.object_id)?;
            crate::mcp_project_tools::mcp_project_tools_validation::confine_tool_paths(&[(
                "artifact_path",
                &args.artifact_path,
            )])?;
            let lowered = $lower_fn(&args.document_path, &args.object_id)?;
            let readback = $write_fn(&args.artifact_path, &lowered)?;
            Ok(output(route, $source, p2_artifact(&readback)?, None, None))
        }

        pub(crate) fn $read_handler(
            route: McpDomainTool,
            arguments: Value,
        ) -> Result<McpObjectToolCallOutput, EngineError> {
            let args: ReadLoweredUnitArgs = parse_args($read_tool, arguments)?;
            validate_path("artifact_path", &args.artifact_path)?;
            validate_single_line("expected_fingerprint", &args.expected_fingerprint)?;
            let readback = $read_fn(&args.artifact_path, &args.expected_fingerprint)?;
            Ok(output(
                route,
                "fingerprinted litd/data TOML artifact re-read from disk + fingerprint verified",
                p2_artifact(&readback)?,
                None,
                None,
            ))
        }
    };
}

p2_lowering_handlers!(
    lower_buff,
    read_lowered_buff,
    LOWER_BUFF_TOOL,
    READ_LOWERED_BUFF_TOOL,
    crate::object_editor::lower_buff_from_document_path,
    crate::object_editor::write_lowered_buff_toml,
    crate::object_editor::read_lowered_buff_toml,
    "Calyx Aster buff object -> #829 lowering valve -> fingerprinted litd/data buff TOML re-read from disk"
);
